/*
 * prog43_catalan – reconstructed from the obfuscated binary
 *
 * Behaviour (as observed from the original binary):
 *
 *   * If no command‑line argument is supplied:
 *         prints "NO_INPUT" and exits.
 *
 *   * If the argument cannot be parsed as a decimal integer,
 *     contains extra characters, or is not a positive integer:
 *         prints "BAD_INPUT" and exits.
 *
 *   * If the integer is larger than the supported range (30):
 *         prints "OUT_OF_RANGE" and exits.
 *
 *   * Otherwise the program computes the n‑th Catalan number
 *     (with n ≥ 1) using a simple DP recurrence and prints it.
 *
 * The program matches the observable stdout of the original binary.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAX_N 30          /* size of the table used in the original binary */

int main(int argc, char *argv[])
{
    /* ---------- NO_INPUT ---------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- parse the argument ---------- */
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* strtol failed to consume any characters */
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }

    /* extra characters after the number */
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* negative numbers or zero are not accepted */
    if (n <= 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- range check ---------- */
    if (n > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- compute Catalan numbers ---------- */
    unsigned long long cat[MAX_N + 1] = {0};
    cat[0] = 1;                     /* C0 = 1 */

    for (int i = 1; i <= n; ++i) {
        unsigned long long sum = 0;
        for (int j = 0; j < i; ++j) {
            sum += cat[j] * cat[i - 1 - j];
        }
        cat[i] = sum;
    }

    /* ---------- output ---------- */
    printf("%llu\n", cat[n]);

    return 0;
}
